CREATE OR REPLACE FUNCTION public.ds_claim_stripe_webhook_event(p_id text, p_type text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'AS $function$declare changed integer;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Service role required';end if; if p_id !~ '^evt_[A-Za-z0-9_]+$' or length(p_id)>255 then raise exception 'Invalid event ID';end if; insert into public.ds_stripe_webhook_events(event_id,event_type) values(p_id,p_type) on conflict do nothing; get diagnostics changed=row_count; if changed=1 then return true;end if; update public.ds_stripe_webhook_events set claimed_at=now(),state='processing' where event_id=p_id and state='processing' and claimed_at<now()-interval '5 minutes'; get diagnostics changed=row_count; return changed=1;end $function$;
CREATE OR REPLACE FUNCTION public.ds_finish_stripe_webhook_event(p_id text, p_success boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'AS $function$begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Service role required';end if; if p_success then update public.ds_stripe_webhook_events set state='completed',completed_at=now() where event_id=p_id; else delete from public.ds_stripe_webhook_events where event_id=p_id and state='processing';end if;end $function$;